def calculate_skew(dna_string):
    skew = [0]  # Initialize skew list with the first value as 0
    for nucleotide in dna_string:
        if nucleotide == 'G':
            skew.append(skew[-1] + 1)  # Increment skew by 1 for 'G'
        elif nucleotide == 'C':
            skew.append(skew[-1] - 1)  # Decrement skew by 1 for 'C'
        else:
            skew.append(skew[-1])  # Keep skew the same for other nucleotides
    return skew


def minimum_skew(dna_string):
    skew_values = calculate_skew(dna_string)
    min_skew = min(skew_values)  # Find the minimum skew value
    min_positions = [
        i for i, value in enumerate(skew_values) if value == min_skew
    ]  # Get all positions with minimum skew
    return min_positions


if __name__ == "__main__":
    dna_string = "GAGCCACCGCGATA"
    print("DNA string:", dna_string, "\n")

    skew_values = calculate_skew(dna_string)
    print("Space separated skew values for i ranging from 0 to len(dna_string):")
    print(" ".join(map(str, skew_values)), "\n")

    min_positions = minimum_skew(dna_string)
    print("Space separated minimum skew position(s):")
    print(" ".join(map(str, min_positions)))


